import { useCallback, useEffect, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';

import { Button } from '../components/Button';
import ExpoSpeechBenchmark from '../modules/expo-speech-benchmark/src/ExpoSpeechBenchmarkModule';
import type { SpeechAuthorizationStatus } from '../modules/expo-speech-benchmark/src/ExpoSpeechBenchmark.types';

const STATUS_LABEL: Record<SpeechAuthorizationStatus, string> = {
  notDetermined: 'Speech access: not requested',
  authorized: 'Speech access: granted',
  denied: 'Speech access: denied',
};

function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

export default function TranscribeScreen() {
  const [status, setStatus] = useState<SpeechAuthorizationStatus>('notDetermined');
  const [errorText, setErrorText] = useState<string | null>(null);
  const [transcribing, setTranscribing] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [elapsedSeconds, setElapsedSeconds] = useState<number | null>(null);

  useFocusEffect(
    useCallback(() => {
      setErrorText(null);
      try {
        setStatus(ExpoSpeechBenchmark.getAuthorizationStatus());
      } catch (err) {
        setErrorText(errorMessage(err));
      }
    }, [])
  );

  useEffect(() => {
    const subscription = ExpoSpeechBenchmark.addListener('onPartialTranscript', (event) => {
      setTranscript(event.text);
    });
    return () => subscription.remove();
  }, []);

  const handleRequestAccess = useCallback(async () => {
    setErrorText(null);
    try {
      const result = await ExpoSpeechBenchmark.requestAuthorization();
      setStatus(result);
    } catch (err) {
      setErrorText(errorMessage(err));
    }
  }, []);

  const handleTranscribe = useCallback(async () => {
    setErrorText(null);
    setTranscript('');
    setElapsedSeconds(null);
    setTranscribing(true);
    const startedAt = Date.now();
    try {
      const finalTranscript = await ExpoSpeechBenchmark.transcribe();
      setTranscript(finalTranscript);
      setElapsedSeconds((Date.now() - startedAt) / 1000);
    } catch (err) {
      setErrorText(errorMessage(err));
    } finally {
      setTranscribing(false);
    }
  }, []);

  const statusLine = errorText ?? (transcribing ? 'Transcribing…' : STATUS_LABEL[status]);

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{statusLine}</Text>
      <View style={styles.buttons}>
        <Button label="Request Access" onPress={handleRequestAccess} />
        <Button
          label="Transcribe Sample"
          onPress={handleTranscribe}
          disabled={status !== 'authorized' || transcribing}
        />
      </View>
      <View style={styles.transcriptArea}>
        {transcript ? (
          <>
            <Text style={styles.transcript}>{transcript}</Text>
            {elapsedSeconds !== null && (
              <Text style={styles.elapsed}>Completed in {elapsedSeconds.toFixed(1)} s</Text>
            )}
          </>
        ) : (
          <Text style={styles.emptyState}>No transcript yet</Text>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 24,
    gap: 16,
  },
  status: {
    fontSize: 16,
  },
  buttons: {
    gap: 12,
  },
  transcriptArea: {
    marginTop: 16,
    gap: 8,
  },
  transcript: {
    fontSize: 15,
    lineHeight: 22,
  },
  elapsed: {
    fontSize: 13,
    color: '#6b7280',
  },
  emptyState: {
    fontSize: 15,
    color: '#6b7280',
  },
});

